const selectedByProfile = new Map();
export function setSelectedCookieSnapshot(profileId, snapshotId) {
  const profile = String(profileId ?? "").trim();
  if (!profile) return;
  const snapshot = String(snapshotId ?? "").trim();
  if (snapshot) selectedByProfile.set(profile, snapshot);else selectedByProfile.delete(profile);
}
export function getSelectedCookieSnapshot(profileId) {
  return selectedByProfile.get(String(profileId ?? "").trim());
}
